{
 "nctId": "NCT07672236",
 "briefTitle": "A Clinical Study to Compare BupiZenge With Lidocaine for Pain Due to Oral Mucositis in Patients With Head and Neck Cancer.",
 "officialTitle": "A Randomized, Open-label, Phase III Trial to Assess the Efficacy and Safety of BupiZenge Compared to Lidocaine for Pain Associated With Oral Mucositis in Head and Neck Cancer",
 "leadSponsor": {
  "name": "OncoZenge AB",
  "class": "INDUSTRY"
 },
 "collaborators": [
  {
   "name": "Link Medical Research AB",
   "class": "INDUSTRY"
  }
 ],
 "startDate": "2026-07-07",
 "firstRegistered": "2026-06-17",
 "hasDataMonitoringCommittee": false,
 "conditions": [
