{
 "nctId": "NCT07017777",
 "briefTitle": "A Study to Evaluate the Immunogenicity and Safety of 13-valent Pneumococcal Conjugate Vaccine (PCV13i) in Healthy Infants Aged 2 Months (Minimum 6 Weeks)",
 "officialTitle": "A Phase III, Observer-blind, Randomized Controlled Trial to Evaluate the Immunogenicity and Safety of 13-valent Pneumococcal Conjugate Vaccine (PCV13i) in Healthy Infants Aged 2 Months (Minimum 6 Weeks)",
 "leadSponsor": {
  "name": "CanSino Biologics Inc.",
  "class": "INDUSTRY"
 },
 "startDate": "2025-11-14",
 "firstRegistered": "2025-06-04",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Pneumococcal Infections",
  "Streptococcal Infections",
  "Bacterial Infections"
 ],
 "keywords": [
  "PCV13i",
  "13 valent Pneumococcal conjugate vaccine",
  "Pneumococcal infections",
  "2 months of age",
  "Safety",
  "Immunogenicity"
 ],
 "phases": [
  "PHASE3"
 ],
 "design": {
  "allocation": "RANDOMIZED",
