   ]
  },
  {
   "type": "BIOLOGICAL",
   "name": "Prevnar 13",
   "description": "3 doses: 2 months (Dose 1) months (Dose 2), 12-15 months (Booster dose)",
   "armGroupLabels": [
    "Pneumococcal 13-valent Conjugate Vaccine (Prevnar 13)"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Proportion of participants achieving serotype-specific IgG antibody concentrations ≥ 0.35 µg/mL",
   "timeFrame": "30 days after the booster dose"
  },
  {
   "measure": "Incidence of solicited local and systemic adverse events (AEs)",
   "timeFrame": "Within 7 days after each dose of vaccination"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Incidence of unsolicited adverse events",
   "timeFrame": "Within 30 days after each dose of vaccination"
  },
  {
   "measure": "The number of serious adverse events (SAEs)",
   "timeFrame": "Through study completion, an average of 16-19 months"
  },
  {
   "measure": "The geometric mean concentration (GMC) of Serotype-specific IgG in all participants",
   "timeFrame": "Before vaccination and 30 days after the booster dose"
  },
  {
   "measure": "Proportion of participants achieving serotype-specific IgG antibody concentrations ≥ 0.35 µg/mL in Sub-cohort A participants",
   "timeFrame": "30 days after the primary series"
  },
  {
   "measure": "Proportion of participants achieving serotype-specific IgG antibody concentrations ≥ 0.35 µg/mL in Sub-cohort B participants",
   "timeFrame": "Before the booster dose"
  },
  {
   "measure": "The geometric mean concentration (GMC) of Serotype-specific IgG in Sub-cohort A participants",
   "timeFrame": "30 days after the primary series"
  },
  {
   "measure": "The geometric mean concentration (GMC) of Serotype-specific IgG in Sub-cohort B participants",
   "timeFrame": "Before the booster dose"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n* Healthy infants with stable clinical conditions aged 2 months (42-90 days) at the time of screening, based on medical history and clinical assessment by the investigator. Infants will be eligible starting from the day they turn 6 weeks of age.\n* Infant's parent or legal guardian must be able and willing to provide informed consent for the infant's participation in the study.\n* Participants and their parent or legal guardian must demonstrate the ability to comply with all trial procedures and be available for the entire follow-up duration.\n* The infant's parent or legal guardian must have an easily identifiable and stable place of residence within the study area, be available for the duration of trial participation, and have access to a reliable means of telephone contact for communication with the study team.\n\nExclusion Criteria for the first dose:\n\n* Infants born at \\<35 weeks of gestation.\n* Infants who have previously received any pneumococcal vaccine.\n* Infants currently participating in or who have recently participated in another interventional clinical trial.\n* Infants with an axillary temperature of ≥37.8°C at the time of enrollment (the participant must be deferred until recovery. The visit may be rescheduled when this criterion is met.)\n* Infants with any congenital abnormalities, chronic medical conditions, or genetic disorders, severe malnutrition, inherited disease and others, that in the investigator's judgment, may interfere with the study outcomes.\n* History of anaphylactic shock\n* History of allergic disease or history of a serious reaction to any prior vaccination or known hypersensitivity to any component of the experimental and control vaccine\n* History of epilepsy and convulsions.\n* Have received immunosuppressive treatment, cytotoxic treatment, systemic steroid treatment for more than 2 weeks, etc. (excluding local treatment, surface treatment of acute non-concurrent dermatitis, or spray treatment of allergic rhinitis).\n* Received or planned to receive blood/plasma products or immunoglobulins throughout the study period or prior to study vaccination.\n* History of coagulation disorders or blood conditions that could cause anemia or excess bleeding as judged by the investigator.\n* Infants with known or suspected immunodeficiency, as determined by medical history and/or physical examination.\n* Administration of other vaccines within 7 days prior to enrollment.\n* Any history or current evidence of a condition or therapy that could confound study results, interfere with participation, or is not in the best interest of the participant, as judged by the investigator.\n* The participant is a direct descendant (child or grandchild) of any person employed by the Sponsor, the contract research organization (CRO), the investigator, or study site personnel.\n* Any other condition or situation that, in the investigator's judgment, might interfere with the study or pose additional risks to the participant.\n\nIndividual termination criteria for subsequent doses:\n\n* Severe allergic reaction after the previous vaccination.\n* Serious adverse events caused by the previous vaccination that is not suitable for subsequent vaccination(s) as judged by the investigator.\n* Newly identified symptoms or newly occurred cases after the first vaccination that do not meet the inclusion criteria for the first dose, or that meet the exclusion criteria for the first dose. The decision to discontinue participation is determined by the investigator.\n* Other reasons for exclusion considered by the investigator.",
  "healthyVolunteers": true,
  "sex": "ALL",
  "minimumAge": "6 Weeks",
  "maximumAge": "2 Months"
 },
