 "primaryOutcomes": [
  {
   "measure": "Change from baseline in the morning pre-dose forced vital capacity at Week 12",
   "timeFrame": "From enrollment to the end of treatment at 12 weeks"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Time to disease progression",
   "description": "Disease progression is defined as forced vital capacity (FVC) percent predicted decline of ≥10% prior to Week 12, respiratory hospitalization, or death.",
   "timeFrame": "From enrollment to the end of treatment at 12 weeks"
