{
 "nctId": "NCT05672576",
 "briefTitle": "A Research Study to Evaluate the Efficacy and Safety of Cenerimod in Subjects Suffering From Systemic Lupus Erythematosus",
 "officialTitle": "A Phase 3, Multicenter, Randomized, Double-blind, Placebo-controlled, Parallel-group Study to Evaluate the Efficacy, Safety, and Tolerability of Cenerimod in Adult Subjects With Moderate-to-severe Systemic Lupus Erythematosus (SLE) on Top of Background Therapy",
