{
 "nctId": "NCT06636682",
 "briefTitle": "FK-PC101 as Adjuvant Therapy for Men With High-Risk Prostate Cancer",
 "officialTitle": "A Multicenter, Adaptive, Phase 2, Randomized, Open-label Study of Irradiated Autologous Cellular Vaccine in Men With High-Risk Prostate Cancer Following Prostatectomy",
 "leadSponsor": {
  "name": "Cellvax Therapeutics Inc",
  "class": "INDUSTRY"
 },
 "startDate": "2024-10-14",
 "firstRegistered": "2024-10-08",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Prostate Cancer (Adenocarcinoma)",
  "Prostate CA",
  "Prostate Cancers",
  "Prostate Cancer (Post Prostatectomy)",
  "Prostate Cancer",
  "Prostate Cancer Patients Undergoing Radical Prostatectomy",
  "High-risk Prostate Cancer"
 ],
 "keywords": [
