 "design": {
  "allocation": "RANDOMIZED",
  "interventionModel": "PARALLEL",
  "primaryPurpose": "TREATMENT",
  "maskingInfo": {
   "masking": "NONE"
  }
 },
 "enrollment": 90,
 "briefSummary": "The goal of this clinical trial is to learn if using a liver-directed therapy with high dose chemotherapy followed by approved cancer treatment to treat patients with colorectal cancer that has spread to the liver is safe and tolerable. The clinical trial will also learn if the liver-directed therapy with high dose chemotherapy works on the disease in the liver. Investigators will compare the use of the liver-directed therapy with high dose chemotherapy followed by approved cancer treatment or approved cancer treatment alone.\n\nParticipants will:\n\n* Undergo up to two liver-directed therapy with high dose chemotherapy procedures followed by approved cancer treatment or take approved cancer treatment alone\n* Visit clinic at least every two weeks for checkups and tests\n* Complete scans approximately every two months",
 "detailedDescription": "This is an open-label, randomized, multi-center study in which patients with liver dominant refractory mCRC will be randomized 2:1 to receive melphalan/HDS (2 cycles) followed by trifluridine-tipiracil plus bevacizumab treatment (Arm A) or trifluridine-tipiracil plus bevacizumab alone (Arm B).\n\nApproximately 90 patients will be randomized 2:1 to the two treatment arms (Arm A, n=60; Arm B, n=30). Patients will receive one of the following treatments within 14 days of randomization:\n\n* Arm A: Patients will be treated with melphalan/HDS 3.0 mg/kg ideal body weight (IBW) for two treatment cycles. The second melphalan/HDS treatment will be administered 6 weeks after the first treatment with an acceptable delay of up to 2 weeks (8 weeks total) to allow for recovery of melphalan-related toxicity, if needed. Tumor response will be assessed prior to Cycle 2 of melphalan/HDS (6 to 8 weeks after Cycle 1 melphalan/HDS treatment), at the end of Week 16 (+/- 7 days), and every 8 weeks (+/- 7 days) thereafter during trifluridine-tipiracil plus bevacizumab treatment.\n* Arm B: Patients will be treated with standard regimen of trifluridine-tipiracil and bevacizumab.\n\nIn both treatment arms, treatment with trifluridine-tipiracil plus bevacizumab will continue until disease progression, death, intolerable adverse events, consent withdrawal, principal investigator decision, or termination of study by Sponsor.\n\nCross-over: There will be no cross-over between the two arms of the study. Efficacy and Safety Assessment: Evaluation of tumor response will be determined by the local principal investigator using RECIST 1.1 criteria. Tumor response evaluation and patient management will be according to the principal investigator assessment of images and patients' clinical needs. Patients with progressive disease (PD) will be discontinued from study treatment and will be followed for survival until withdrawal of consent or death.\n\nStudy treatment will be discontinued if recovery from treatment related toxicity requires more than 2 weeks from the end of the treatment cycle during melphalan/HDS cycles (Arm A only), or more than a 28-day delay in the start of the next cycle of trifluridine-tipiracil plus bevacizumab; the end of treatment (EOT) visit will be conducted at that time or within 4 weeks.\n\nSafety will be monitored continuously by documentation of AEs, SAEs, clinical laboratory measurements, vital signs, and physical examination.\n\nData Safety Monitoring Board (DSMB): A DSMB including independent (non-investigator) clinicians will oversee the emerging patient safety profile during the study. The DSMB will review study data on a regular basis according to the DSMB Charter.",
 "arms": [
  {
   "label": "Melphalan/HDS followed by Consolidation Treatment with Trifluridine-tipiracil plus Bevacizumab",
   "type": "EXPERIMENTAL",
   "description": "Melphalan/HDS is given as an infusion of Melphalan into the hepatic artery under general anesthesia. This treatment is administered twice, 8 weeks apart. Following 2 treatments with Melphalan/HDS, Trifluridine-tipiracil is given 35 mg/m2 up to a maximum of 80 mg per dose orally twice daily with food on Days 1 through 5 and Days 8 through 12 of each 28-day cycle; and intravenous (IV) bevacizumab 5 mg/kg body weight on Days 1 and 15 of each 28-day cycle until disease progression or unacceptable toxicity",
   "interventionNames": [
    "Drug: Melphalan/HDS Followed by Consolidation Treatment with Trifluridine-tipiracil plus Bevacizumab"
   ]
  },
  {
   "label": "Trifluridine-tipiracil plus Bevacizumab Alone",
   "type": "ACTIVE_COMPARATOR",
   "description": "Trifluridine-tipiracil plus Bevacizumab is the standard of care for patients with metastatic colorectal cancer. Trifluridine-tipiracil is given 35 mg/m2 up to a maximum of 80 mg per dose orally twice daily with food on Days 1 through 5 and Days 8 through 12 of each 28-day cycle; and intravenous (IV) bevacizumab 5 mg/kg body weight on Days 1 and 15 of each 28-day cycle until disease progression or unacceptable toxicity",
   "interventionNames": [
    "Drug: Trifluridine-tipiracil plus Bevacizumab Alone"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
   "name": "Melphalan/HDS Followed by Consolidation Treatment with Trifluridine-tipiracil plus Bevacizumab",
