   "interventionNames": [
    "Drug: Allocetra"
   ]
  },
  {
   "label": "Placebo",
   "type": "PLACEBO_COMPARATOR",
   "description": "Three intra-articular injections of placebo into the index knee.",
   "interventionNames": [
    "Other: Placebo"
   ]
  }
 ],
 "interventions": [
  {
   "type": "DRUG",
