   "armGroupLabels": [
    "Arm A: GHK-Cu Gel (0.1% w/w) applied once daily to the assigned wound for 14 days + standard non-adh",
    "Arm B: Vehicle Gel applied once daily to the assigned wound for 14 days + standard non-adherent dres"
   ]
  },
  {
