 "primaryOutcomes": [
  {
   "measure": "Change in Blister Surface Area of the Designated Treatment Area(s)",
   "description": "Clinical photography will be used to assess changes in disease severity within the target lesional area (TLA) and recurrence of blistering by measuring blister surface area in the designated TLA over time.",
   "timeFrame": "Day 1 (Baseline) and weekly until End of Study (2-months and maximum 4-months)"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Plantar Blister Surface Area Reduction",
   "description": "Plantar blister surface area changes over time will be examined using clinical photography for localized EBS patients that treat their feet and those intermediate to severe EBS subjects that opt-in to treat their feet.",
   "timeFrame": "Day 1 (Baseline) and weekly until End of Study (2-months and maximum 4-months)"
  },
  {
   "measure": "Subject-reported Pain Score in Target Lesional Areas During Treatment Application",
   "description": "Using the adult or pediatric PROMIS® Measure form, peak pain during treatment application will be reported on a weekly basis until Part 2 End of Study (EOS, 4-months), with a possible assessment at the 6-month follow up visit. Pain trends in TolaSure Gel, 5% w/w and Placebo groups will be compared. The following PROMIS® Measure forms will be used depending on the patient's age: The Adult Pain Interference-Short Form 8a, Pediatric Pain Interference-Short Form 8a, and Parent Proxy Pain Interference-Short Form 8a. These scales are from 1 to 5 and relate to how much pain interferes with daily activities, with 1 indicating Never/Not at All and 5 indicating Almost Always/Very Much. For 2-4 year-old subjects, worst pain Numeric Rating Scale (NRS) questionnaire will be reported by caregivers/guardians. Pain NRS is from 0 to 10 with 0=no pain and 10=worst pain imaginable.",
   "timeFrame": "Day 1 (Baseline) and weekly until End of Study (2-months and maximum 4-months)"
  },
  {
   "measure": "Subject-reported Itch Score in Target Lesional Area",
   "description": "Using the adult or pediatric PROMIS® Measure form, itch characteristics will be reported on a weekly basis until Part 2 End of Study (EOS, 4-months), with a possible assessment at the 6-month follow up visit. Itch trends in TolaSure Gel, 5% w/w and Placebo groups will be compared. The following PROMIS® Measure forms will be used depending on the patient's age: The Adult Itch Interference-Short Form 8a, Pediatric Itch-Short Form 8a (PIQ-C), and Parent Proxy Itch-Short Form 8a (PIQ-C). These scales are from 1 to 5 and relate to how much itch interferes with daily activities and the level of itch, with 1 indicating Never/No Itch and 5 indicating Almost Always/Very Severe. For 2-4 year-old subjects, worst scratch/itch Numeric Rating Scale (WSI-NRS) questionnaire will be reported by caregivers/guardians. WSI-NRS is from 0 to 10 with 0=no itching or scratching and 10=worst imaginable itching or scratching.",
   "timeFrame": "Day 1 (Baseline) and weekly until End of Study (2-months and maximum 4-months)"
  },
  {
   "measure": "Subject-reported Quality of Life (QoL)",
   "description": "Patient's quality of life (QoL) metrics, highlighting symptoms and daily living concerns of EBS patients, will be reported at Visit 2/ Baseline, Part 1 End of Study (EOS), and Part 2 EOS, with a possible assessment at the 6-month follow up visit. This QoL assessment will be given to patients in a questionnaire format. The questions focus on how EBS blistering areas affect daily physical and social activities as well as mental and emotional health. The scale range is from 0 to 10, with 0 being not at all affected and 10 being severely affected. QoL metrics in TolaSure Gel, 5% w/w and Placebo control groups will be examined.",
   "timeFrame": "Day 1 (Baseline), Part 1 End of Study (2-months), Part 2 End of Study (4-months)"
  },
  {
   "measure": "Subject-reported Modified Foot Function Index (mFFI)",
   "description": "Patient's modified Foot Function Index (mFFI), is a questionnaire about foot pathology as it relates to pain, disability, and/or activity restrictions. Questions relating to pain are on a 0 to 10 scale with 0 being no pain at all and 10 being the worst pain imaginable. Daily activity scores also range from 0 to 10 with 0 being Not at All/Not Difficult at All and 10 being All the Time/So Difficult. The mFFI questionnaire will be reported at Visit 2/ Baseline, Part 1 End of Study (EOS), and Part 2 EOS, with a possible assessment at the 6-month follow up visit. mFFI metrics in TolaSure Gel, 5% w/w and Placebo control groups will be examined.",
   "timeFrame": "Day 1 (Baseline), Part 1 End of Study (2-months), Part 2 End of Study (4-months)"
