{
 "nctId": "NCT07142044",
 "briefTitle": "Safety, Tolerability and Exploratory Efficacy of EC5026 in Parkinson's Disease (STEP Study)",
 "officialTitle": "Safety, Tolerability and Exploratory Efficacy of EC5026 in Parkinson's Disease (STEP Study)",
 "leadSponsor": {
