 ],
 "startDate": "2025-11-01",
 "firstRegistered": "2025-08-19",
 "hasDataMonitoringCommittee": true,
 "conditions": [
  "Parkinson&#39;s Disease (PD)"
 ],
 "keywords": [
  "EC5026",
  "Parkinson&#39;s Disease",
