 "primaryOutcomes": [
  {
   "measure": "Time to the first recurrence of chronic bacterial cystitis",
   "description": "Criteria for the diagnosis of chronic bacterial cystitis recurrence are typical symptoms of exacerbation (acute cystitis): frequent urination with small volumes of urine; urgent urination (a sudden and uncontrollable urge to pass urine; feeling pain or burning when passing urine; feeling of incomplete bladder emptying after urination; pain or uncomfortable pressure in the lower abdomen (above the pubis); possible presence of blood in the urine (especially towards the end of urination).\n\nCriteria for the diagnosis of chronic bacterial cystitis are 2 and more recurrences during previous 6 months or 3 and more recurrences during previous 12 months.",
   "timeFrame": "6 months"
  }
 ],
 "secondaryOutcomes": [
