 "primaryOutcomes": [
  {
   "measure": "Time to Loss of Response in the Epworth Sleepiness Scale (ESS) Score During the Up to 4-Week RW Period",
   "description": "The ESS provides individuals with 8 different situations of daily life and asks them how likely they are to fall asleep in those situations (scored 0 to 3) and to try to imagine their likelihood of dozing even if they have not actually been in the identical situation; the scores are summed to give an overall score of 0 to 24. Higher scores indicate stronger subjective daytime sleepiness, and scores below 10 are considered to be within normal range.",
   "timeFrame": "Up to 4-week RW period"
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From the End of the OL Treatment Period to Week 2 of the RW Period on the Maintenance of Wakefulness Test (MWT)",
   "description": "The MWT evaluates a person's ability to remain awake under soporific conditions for a defined period of time. Because there is no biological measure of wakefulness, wakefulness is measured indirectly by the inability or delayed tendency to fall asleep. This tendency to fall asleep is measured via electroencephalography (EEG)-derived sleep latency in the MWT. The MWT consists of four 40-minute sessions. Sleep latency in each wake trial will be recorded. Participants will be required to stay awake in between the 4 sessions.",
   "timeFrame": "From the end of the OL treatment period (Week 16) to Week 2 of the RW period (Week 18)"
  },
  {
   "measure": "Weekly Cataplexy Rate (WCR) at Week 2 of the RW Period",
   "timeFrame": "Week 2 of the RW period"
  },
  {
   "measure": "Change from the End of the OL Treatment Period to Week 2 of the RW Period in Mean Number of Lapses on the Psychomotor Vigilance Test (PVT)",
   "description": "The PVT is a simple reaction performance task with a duration of 10 minutes that aims to measure sustained attention.",
   "timeFrame": "From the end of the OL treatment period (Week 16) to Week 2 of the RW period (Week 18)"
  },
  {
   "measure": "Number of Participants Reporting Much or Very Much Worse in Patient Global Impression of Change (PGI-C) Score at Week 2 of the RW Period",
   "description": "The PGI-C is a participant self-rated scale to assess improvement in daytime sleepiness and overall narcolepsy symptoms. It measures change due to treatment relative to baseline on a 7-point scale ranging from a score of 1 (\"very much improved\") to score of 7 (\"very much worse\").",
   "timeFrame": "Week 2 of the RW period"
  },
  {
   "measure": "Change from the End of the OL Treatment Period to Week 2 of the RW Period in Narcolepsy Severity Scale for Clinical Trials (NSS-CT) Total Score",
   "description": "The NSS-CT is a 15-item self-administered questionnaire assesses the severity and consequences of the 5 major narcolepsy symptoms such as daytime sleepiness, cataplexy, hallucinations, sleep paralysis, and disturbed night-time sleep (DNS) with a total score range of 0 to 57 (sum of 6 items that assess symptoms severity are rated using a six-point Likert scale \\[0-5\\] and 9 items that describe the symptom effect on daily life are rated using a four-point Likert scale \\[0-3\\]. Higher total scores mean a worse outcome.",
   "timeFrame": "From the end of the OL treatment period (Week 16) to Week 2 of the RW period (Week 18)"
  },
  {
   "measure": "Change from the End of the OL Treatment Period to Week 2 of the RW Period in Functional Impacts of Narcolepsy Instrument (FINI) Domain Scores",
   "description": "The FINI measures the functional impacts of narcolepsy across 6 domains. Each domain is scored from 0 to 4, where 0 indicates the best health and 4 the worst.",
   "timeFrame": "From the end of the OL treatment period (Week 16) to Week 2 of the RW period (Week 18)"
  },
  {
   "measure": "Change from the End of the OL Treatment Period to Week 2 of the RW Period in Number of Correct Responses on the International Digit Symbol Substitution Test-symbols (iDSST-s)",
   "description": "The iDSST-s is a processing speed test that is based on the pre-existing pencil and paper version of the Digit Symbol Substitution Test. The participants are presented with a legend that defines 9 symbols, with each symbol corresponding to a digit from 1 to 9. The participant is then presented with a conveyer belt in the middle of the screen that displays a series of empty boxes labelled with a number. The participant must select the symbol that corresponds to the number of a given highlighted box from symbol options presented at the bottom of the screen. The participant must try to place as many correct symbols in the boxes as possible over the duration of the test.",
   "timeFrame": "From the end of the OL treatment period (Week 16) to Week 2 of the RW period (Week 18)"
  },
  {
   "measure": "Number of Participants With At Least One Treatment-Emergent Adverse Event (TEAE)",
   "description": "An adverse event (AE) is any untoward medical occurrence in a clinical investigation participant administered a pharmaceutical product. A TEAE is defined as any event emerging or manifesting at or after the initiation of treatment with a study intervention or medicinal product or any existing event that worsens in either intensity or frequency following exposure to the study intervention or medicinal product.",
   "timeFrame": "From Screening to End of study (approximately 31 weeks)"
  }
 ],
 "eligibility": {
  "criteria": "Inclusion Criteria:\n\n1. The participant has a body mass index (BMI) within the range 18 to 40 kilograms per square meter (kg/m\\^2).\n2. The participant has an International Classification of Sleep Disorders, Third Edition (ICSD-3) or International Classification of Sleep Disorders, Third Edition, Text Revision (ICSD-3-TR) diagnosis of NT1.\n3. The participant is positive for the human leukocyte antigen (HLA) genotype Major Histocompatibility Complex, Class II, DQ Beta 1 (HLA-DQB1\\*06:02) or results from radioimmunoassay indicate the participant's CSF OX/hypocretin-1 concentration is ≤110 pg/mL (or less than one-third of the mean values obtained in normal participants within the same standardized assay).\n\nExclusion Criteria:\n\n1. The participant has a current medical disorder, other than narcolepsy with cataplexy, associated with EDS.\n2. The participant a) has a history of myocardial infarction, b) has a history of clinically significant hepatic disease, thyroid disease, coronary artery disease, cardiac rhythm abnormality or heart failure, or c) has any medical condition (such as unstable cardiovascular, pulmonary, renal or gastrointestinal disease.\n3. The participant has current or recent (within 6 months) gastrointestinal disease that is expected to influence the absorption of drugs.\n4. The participant has a history of cancer in the past 5 years.\n5. The participant has a clinically significant history of head injury or head trauma.\n6. The participant has a history of epilepsy, seizure, or convulsion (except for a single febrile seizure in childhood).\n7. The participant has a history of cerebral ischemia, transient ischemic attack (less than 5 years from screening), intracranial aneurysm, or arteriovenous malformation.",
