{
 "nctId": "NCT07565506",
 "briefTitle": "Phase 2a Dose Finding Study of Nu-3 Gel in Subjects With Mild iDFU",
 "officialTitle": "A Prospective, Randomized, Single-Blind Phase 2a Multi-Center Dose Comparative Study to Evaluated The Safety, Tolerability, and Antimicrobial Efficacy Of Topically Twice Daily Applied Bisphosphocin Nu-3 Gel At a 2%, 5%, And 10% Concentration To Infected Diabetic Foot Ulcers (iDFU)",
 "leadSponsor": {
  "name": "Lakewood-Amedex Inc",
  "class": "INDUSTRY"
 },
 "startDate": "2026-08-14",
 "firstRegistered": "2026-04-27",
 "hasDataMonitoringCommittee": false,
 "conditions": [
  "Diabetic Foot Ulcers (DFUs)"
 ],
 "keywords": [
  "diabetic foot ulcer",
  "infection",
  "mildly infected diabetic foot ulcer",
  "iDFU"
 ],
 "phases": [
  "PHASE2"
 ],
 "design": {
  "allocation": "RANDOMIZED",
