   "description": "Matching placebo capsules identical in appearance to DLBS1442 capsules. Participants will receive either one placebo capsule together with one DLBS1442 100 mg capsule or two placebo capsules three times daily for up to 5 consecutive days during one menstrual cycle, according to the randomized treatment assignment.\n\nTreatment may be discontinued once complete pain relief is achieved (Visual Analogue Scale \\[VAS\\] = 0).",
   "armGroupLabels": [
    "DLBS1442 100 mg",
    "Placebo of DLBS1442"
   ]
  }
 ],
 "primaryOutcomes": [
  {
   "measure": "Change From Baseline in Visual Analogue Scale (VAS) Pain Score Within 6 Hours After the First Dose",
   "description": "Change from baseline in menstrual pain intensity measured using the Visual Analogue Scale (VAS). The VAS ranges from 0 to 10, where 0 indicates no pain and 10 indicates the worst imaginable pain. Pain assessments will be performed at baseline and at 30 minutes, 1 hour, 2 hours, 4 hours, and 6 hours after the first dose.",
   "timeFrame": "Baseline to 6 hours after the first dose."
  }
 ],
 "secondaryOutcomes": [
  {
   "measure": "Change From Baseline in Visual Analogue Scale (VAS) Pain Score During the 5-Day Treatment Period",
   "description": "Change from baseline in menstrual pain intensity measured using the Visual Analogue Scale (VAS). The VAS ranges from 0 to 10, where 0 indicates no pain and 10 indicates the worst imaginable pain. Pain assessments will be performed before each scheduled study drug administration during the treatment period.",
   "timeFrame": "Baseline through Day 5"
