 "secondaryOutcomes": [
  {
   "measure": "Percentage of participants achieving validated Investigator Global Assessment scale for Atopic Dermatitis (vIGA-AD) 0/1 with a reduction from Baseline of ≥ 2 points",
   "description": "vIGA-AD is a validated assessment instrument used in clinical studies to rate the severity of AD globally. A 5-point scale is used to measure the severity of disease at the time of the investigator's evaluation of the participant ranging from 0 - Clear (no inflammatory signs of atopic dermatitis (no erythema, no induration/papulation, no lichenification, no oozing/crusting). Post-inflammatory hyperpigmentation and/or hypopigmentation may be present.) to 4 - Severe (marked erythema (deep or bright red), marked induration/papulation, and/or marked lichenification.",
   "timeFrame": "At Week 12"
  },
