 "primaryOutcomes": [
  {
   "measure": "To determine and evaluate the safety and tolerability of Dysplasix™ intravaginal suppository therapy in females with hr-HPV and positive cytology for either ASCUS or LSIL.",
   "description": "Number of participants with serious adverse events (SAEs) or dose-limiting toxicities (DLTs) related to the study intervention assessed using relevant Common Terminology Criteria for Adverse Events (CTCAE).",
   "timeFrame": "From enrollment until post-end of treatment follow up (Day 50 visit)"
  },
